'@
[System.IO.File]::WriteAllBytes($archive, [Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne '3dbf08c80b05282e1f91833c1c1e29da5bf11fac2aac68e6bf1d3b58ac9291cc') { throw 'Pacote incorreto. Nada foi aplicado.' }
Expand-Archive -LiteralPath $archive -DestinationPath $temp
$executor = (Get-Process -Id $PID).Path
& $executor -NoProfile -ExecutionPolicy Bypass -File (Join-Path $temp 'Aplicar-armazenamento.ps1') -Projeto $Projeto
if ($LASTEXITCODE -ne 0) { throw 'Aplicacao interrompida. Envie a mensagem do instalador.' }
Copy-Item -LiteralPath (Join-Path $temp 'Medir-armazenamento.ps1') -Destination (Join-Path $Projeto 'Medir-armazenamento.ps1') -Force
if (-not $NaoCompilar) {
    Push-Location $Projeto
    try {
        & (Join-Path $Projeto 'gradlew.bat') assembleDebug
        if ($LASTEXITCODE -ne 0) { throw 'Compilacao falhou. Envie o erro.' }
        Invoke-Item (Join-Path $Projeto 'app/build/outputs/apk/debug')
    } finally { Pop-Location }
}
Write-Host 'Correcao aplicada. Instale o APK por cima da versao atual e abra o aplicativo.'
Write-Host 'A limpeza pode levar alguns minutos. Depois execute Medir-armazenamento.ps1 -Serial CODIGO_DO_CELULAR e envie o TXT.'
